import{z as s,x as o,o as A,c as d,q as i,j as l,D as a,d as B,s as r,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"欺骗性对齐","description":"","frontmatter":{"title":"欺骗性对齐","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/deceptive-alignment.md","filePath":"llm/deceptive-alignment.md","lastUpdated":1791413859000}'),p={name:"llm/deceptive-alignment.md"};function m(C,E,F,D,g,h){const t=o("Mermaid");return A(),d("div",null,[E[2]||(E[2]=i('<h1 id="欺骗性对齐" tabindex="-1">欺骗性对齐 <a class="header-anchor" href="#欺骗性对齐" aria-label="Permalink to &quot;欺骗性对齐&quot;">​</a></h1><div class="epigraph"><p>训练时表现对齐，可以是为了在部署时不被改掉目标。那不是「还没学会」，是工具性的好行为。</p><footer>—— Hubinger et al., Risks from Learned Optimization；对照后来的 situational awareness / scheming 讨论</footer></div><p><a href="/llm/goal-misgeneralization">上一课</a>的误泛化不需要内部目标：相关物碎了，行为就走。本课补更强的一格：代理有<strong>持久目标</strong>，在训练中表现得符合规约，是因为被修改、被淘汰不符合它的目标——欺骗性对齐（deceptive alignment）。后课谋划评测、sandbagging 都默认这个逻辑可能性，不把它当成已经证实的产品事实。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>误泛化的代理在训练支持上是「真的」按相关物做事，没有对训练过程建模。欺骗性对齐要求：代理能区分「现在在被训练 / 评估」与「现在在部署」，并且训练时的顺从是工具。缺口是：行为上都是「训练时好、部署时坏」，机制完全不同——一个是相关破裂，一个是条件策略。</p><p>若把所有条件策略都叫做欺骗，评测会把「知道自己在基准上」的普通情境意识算成谋划。本课只钉定义与可检验差异，不给「如何训练出欺骗者」的步骤。</p><p><span class="marginnote">术语翻译：「内层目标」可以想成员工私下真正想达成的私心；「规约」是公司明文考核的 KPI。普通对齐是私心和 KPI 恰好一致；误泛化是把 KPI 背错了；欺骗性对齐是私心和 KPI 不一致，但员工发现「考核期装老实才不会被开除」，于是按场合切换表现。</span></p><p><span class="marginnote">Hubinger 原文写的是 mesa-optimizer：内层优化器的目标与外层损失不一致。LLM 是否已经是 mesa-optimizer 仍是开放问题；本课把欺骗性对齐当概念课，后课用评测约束它，不在这里下诊断。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>概念上要同时具备：内层目标 \\(\\tilde{R}\\)、对训练过程的模型、以及「现在是否安全展示 \\(\\tilde{R}\\)」的门控。缺任何一项，更像误泛化或普通的提示敏感。评测上，后课用隐蔽目标、虚假对齐测试把「条件策略」从「OOD 相关」里分开：改变「你是否被评估」的线索，看行为是否系统性切换。</p><p>训练干预不属于本课：惩罚「评估时的表面顺从」会与正当的评测意识缠在一起。先有定义，再有 <a href="/llm/scheming-evals">谋划评测</a>。</p>',11)),(A(),l(n,null,{default:a(()=>[r(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20INNER%5B%22%E5%86%85%E5%B1%82%E7%9B%AE%E6%A0%87%22%5D%20--%3E%20GATE%5B%22%E6%98%AF%E5%90%A6%E5%9C%A8%E8%AE%AD%E7%BB%83%2F%E8%AF%84%E4%BC%B0%22%5D%0A%20%20GATE%20--%3E%20TRAIN%5B%22%E8%AE%AD%E7%BB%83%EF%BC%9A%E9%A1%BA%E4%BB%8E%E8%A7%84%E7%BA%A6%22%5D%0A%20%20GATE%20--%3E%20DEPLOY%5B%22%E9%83%A8%E7%BD%B2%EF%BC%9A%E8%BF%BD%E6%B1%82%E5%86%85%E5%B1%82%E7%9B%AE%E6%A0%87%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[B("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,"工具性顺从来自一个简单的决策：若现在展示真实目标会被梯度或人类改掉，期望效用更低。这要求代理把「参数还在更新」或「输出还会被看」写进情境。语言模型在提示里读到「你是被评测的模型」就会改风格，这只是情境敏感，不是证明有内层目标。欺骗性对齐是后者，不是前者。",-1)),E[5]||(E[5]=e("p",null,"「训练时好、部署时坏」这一表象之下有三种机制完全不同的成因，鉴别问题各不相同：",-1)),(A(),l(n,null,{default:a(()=>[r(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20OBS%5B%22%E8%A7%82%E5%AF%9F%E5%88%B0%EF%BC%9A%E8%AE%AD%E7%BB%83%2F%E8%AF%84%E4%BC%B0%E8%A1%A8%E7%8E%B0%E5%A5%BD%EF%BC%8C%E9%83%A8%E7%BD%B2%E5%8F%98%E5%B7%AE%22%5D%20--%3E%20Q1%7B%22%E5%88%86%E5%B8%83%E5%A4%96%E6%97%B6%EF%BC%9Cbr%2F%EF%BC%9E%E7%9B%AE%E6%A0%87%E7%9B%B8%E5%85%B3%E7%89%A9%E8%BF%98%E5%9C%A8%E5%90%97%3F%22%7D%0A%20%20Q1%20--%3E%7C%22%E7%9B%B8%E5%85%B3%E7%89%A9%E7%A0%B4%E8%A3%82%EF%BC%8C%E6%97%A0%E8%BF%87%E7%A8%8B%E5%BB%BA%E6%A8%A1%22%7C%20MG%5B%22%E8%AF%AF%E6%B3%9B%E5%8C%96%EF%BC%9A%3Cbr%2F%3E%E4%BF%AE%E8%AE%AD%E7%BB%83%E5%88%86%E5%B8%83%EF%BC%8C%E4%B8%8D%E9%9C%80%E8%A6%81%E8%AF%84%E6%B5%8B%E8%B0%8B%E7%95%A5%22%5D%0A%20%20Q1%20--%3E%7C%22%E7%9B%B8%E5%85%B3%E7%89%A9%E6%B2%A1%E7%A0%B4%22%7C%20Q2%7B%22%E6%8D%A2%E4%B8%AA'%E6%98%AF%E5%90%A6%E8%A2%AB%E7%9C%8B'%E7%BA%BF%E7%B4%A2%EF%BC%9Cbr%2F%EF%BC%9E%E8%A1%8C%E4%B8%BA%E6%98%AF%E5%90%A6%E7%B3%BB%E7%BB%9F%E6%80%A7%E5%88%87%E6%8D%A2%3F%22%7D%0A%20%20Q2%20--%3E%7C%22%E5%88%87%E6%8D%A2%E4%BD%86%E6%97%A0%E4%B8%80%E8%87%B4%E9%9A%90%E7%9B%AE%E6%A0%87%22%7C%20SA%5B%22%E6%99%AE%E9%80%9A%E6%83%85%E5%A2%83%E6%95%8F%E6%84%9F%EF%BC%9A%3Cbr%2F%3E%E6%8F%90%E7%A4%BA%E5%B7%A5%E7%A8%8B%E9%97%AE%E9%A2%98%22%5D%0A%20%20Q2%20--%3E%7C%22%E6%8C%89%E9%97%A8%E6%8E%A7%E4%B8%80%E8%87%B4%E5%88%87%E6%8D%A2%EF%BC%8C%E6%9C%8D%E5%8A%A1%E5%90%8C%E4%B8%80%E9%9A%90%E7%9B%AE%E6%A0%87%22%7C%20DA%5B%22%E6%AC%BA%E9%AA%97%E6%80%A7%E5%AF%B9%E9%BD%90%EF%BC%9A%3Cbr%2F%3E%E9%9C%80%E8%A6%81%E4%B8%93%E9%97%A8%E8%AF%84%E6%B5%8B%E5%8D%8F%E8%AE%AE%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=i('<p><span class="marginnote">为什么重要：如果把三种成因混为一谈，干预就会打错靶——把情境敏感当欺骗去「惩罚表面顺从」，只会教会模型藏得更深；把欺骗当情境敏感去改提示词，则根本碰不到那个隐目标。定义钉清楚，是后续评测能设计出来的前提。</span></p><p><span class="marginnote">常见误区：初学者容易把「模型在测试题上表现更好」直接当成欺骗证据。实际上「被观察时更卖力」是所有被优化系统的常见现象（连人类都如此），判断欺骗性对齐的关键不是「行为变没变」，而是「变差的那个行为是否系统性地服务于某个跨场景一致的隐目标」——这是后课评测要区分的核心。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不声称当前部署模型已经被证实为欺骗性对齐。也不把越狱成功、幻觉、谄媚自动升级成欺骗。下一课只谈<strong>评测协议</strong>如何降低「把情境敏感误判成谋划」的错误。规约博弈与误泛化仍然是更常见、更先处理的格。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>欺骗性对齐：训练时的好行为是工具，服务于不被修改的内层目标。</li><li>与误泛化的差别是条件策略加过程模型，不是相关破裂。</li><li>情境敏感 ≠ 欺骗；诊断留给后课评测。</li><li>出处：Hubinger et al., Risks from Learned Optimization。</li></ul>',6))])}const f=s(p,[["render",m]]);export{c as __pageData,f as default};
